import{_ as e,o as i,c as t,a4 as a}from"./chunks/framework.BMj-uaUw.js";const k=JSON.parse('{"title":"2.1 Node.js 与版本管理","description":"","frontmatter":{},"headers":[{"level":2,"title":"一个几乎每个人都会遇到的报错","slug":"一个几乎每个人都会遇到的报错","link":"#一个几乎每个人都会遇到的报错","children":[]},{"level":2,"title":"Node 到底是什么","slug":"node-到底是什么","link":"#node-到底是什么","children":[]},{"level":2,"title":"LTS 与 Current 该怎么选","slug":"lts-与-current-该怎么选","link":"#lts-与-current-该怎么选","children":[]},{"level":2,"title":"用 fnm 或 nvm 管版本","slug":"用-fnm-或-nvm-管版本","link":"#用-fnm-或-nvm-管版本","children":[{"level":3,"title":"让项目自己声明要哪个版本","slug":"让项目自己声明要哪个版本","link":"#让项目自己声明要哪个版本","children":[]}]},{"level":2,"title":"engines 字段：项目对 Node 的硬性要求","slug":"engines-字段-项目对-node-的硬性要求","link":"#engines-字段-项目对-node-的硬性要求","children":[]},{"level":2,"title":"常见的“版本不对”报错长什么样","slug":"常见的-版本不对-报错长什么样","link":"#常见的-版本不对-报错长什么样","children":[]},{"level":2,"title":"版本切换后必须做的一件事","slug":"版本切换后必须做的一件事","link":"#版本切换后必须做的一件事","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"常见坑","slug":"常见坑","link":"#常见坑","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"unit02/01-node.md","filePath":"unit02/01-node.md","lastUpdated":1789307994000}'),n={name:"unit02/01-node.md"};function d(o,s,l,p,h,c){return i(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="_2-1-node-js-与版本管理" tabindex="-1">2.1 Node.js 与版本管理 <a class="header-anchor" href="#_2-1-node-js-与版本管理" aria-label="Permalink to &quot;2.1 Node.js 与版本管理&quot;">​</a></h1><h2 id="一个几乎每个人都会遇到的报错" tabindex="-1">一个几乎每个人都会遇到的报错 <a class="header-anchor" href="#一个几乎每个人都会遇到的报错" aria-label="Permalink to &quot;一个几乎每个人都会遇到的报错&quot;">​</a></h2><p>克隆了同学的校园活动服务平台仓库，按 <code>README.md</code> 敲下第一条命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>终端吐出一段红字：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ERR_PNPM_UNSUPPORTED_ENGINE  Unsupported environment (bad pnpm and/or Node.js version)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your Node version is incompatible with &quot;/Users/you/projects/campus-activity-admin&quot;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Expected version: &gt;=20.19.0</span></span>
<span class="line"><span>Got: v18.20.4</span></span></code></pre></div><p>这时候多数人的第一反应是“把 Node 卸了装最新版”。但装最新版有两个风险：一是别的项目 可能又跑不起来；二是下一次换项目还要重来一遍。<strong>正确做法是让机器同时装多个 Node 版本， 按项目切换。</strong></p><p>这一节先把 Node 是什么说清楚，再讲怎么管版本。</p><h2 id="node-到底是什么" tabindex="-1">Node 到底是什么 <a class="header-anchor" href="#node-到底是什么" aria-label="Permalink to &quot;Node 到底是什么&quot;">​</a></h2><p>一句话：<strong>Node 是一个可以脱离浏览器运行 JavaScript 的程序。</strong></p><p>浏览器的 JavaScript 引擎叫 V8，Node 把 V8 抠出来，外面包了一层“能读文件、能开网络端口、 能运行子进程”的能力，就成了 Node。所以 Node 能做的事，浏览器里的 JS 做不了； 浏览器里能做的事（比如操作页面上的 DOM），Node 也做不了 —— 它根本没有 DOM 这个概念。</p><p>在前端工程里，Node 承担两类活：</p><table tabindex="0"><thead><tr><th>角色</th><th>具体例子</th><th>你要不要写这部分代码</th></tr></thead><tbody><tr><td>工具链的运行环境</td><td><code>pnpm</code>、<code>vite</code>、<code>eslint</code>、<code>vitest</code> 都是 Node 程序</td><td><strong>不用写</strong>，只是在用</td></tr><tr><td>本地开发服务器的执行环境</td><td><code>pnpm dev</code> 启动的那个服务器就是 Node 起的</td><td>不用写，但要知道它在跑</td></tr></tbody></table><p>用 <code>exe</code> 和 Windows 的关系类比一下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个 .exe 文件     ←→  一段 JavaScript 工具代码（比如 vite）</span></span>
<span class="line"><span>双击运行           ←→  node ./node_modules/vite/bin/vite.js</span></span>
<span class="line"><span>Windows 操作系统   ←→  Node</span></span></code></pre></div><p>你不需要会写病毒软件，但你的电脑得有个操作系统才能双击 <code>.exe</code>。同理，你不写后端， 但你的机器得装 Node 才能跑 <code>vite</code>。</p><div class="tip custom-block"><p class="custom-block-title">顺手验证一下这个说法</p><p>在项目目录里执行下面这条命令，看看 <code>vite</code> 到底是什么：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require.resolve(&#39;vite/bin/vite.js&#39;))&quot;</span></span></code></pre></div><p>输出是一个 <code>.js</code> 文件的绝对路径。这就是你敲 <code>pnpm dev</code> 时真正被执行的那个文件 —— 它是一段 JavaScript，由 Node 运行。</p><p>理解了这一点，后面看到“Node 版本不对导致构建失败”就不会觉得莫名其妙： <strong>工具的代码是用新语法写的，老版本的 Node 读不懂。</strong></p></div><h2 id="lts-与-current-该怎么选" tabindex="-1">LTS 与 Current 该怎么选 <a class="header-anchor" href="#lts-与-current-该怎么选" aria-label="Permalink to &quot;LTS 与 Current 该怎么选&quot;">​</a></h2><p>Node 的版本分两条线：</p><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>发布节奏</th><th>适合谁</th></tr></thead><tbody><tr><td>Current</td><td>最新特性版本，编号为偶数时进入下一轮候选</td><td>每年 4 月、10 月各发一次</td><td>想试新特性、给 Node 提反馈的人</td></tr><tr><td>LTS（长期支持）</td><td>从 Current 里挑出来的稳定版，维护 30 个月</td><td>每年 10 月转正一次</td><td><strong>绝大多数项目、绝大多数人</strong></td></tr></tbody></table><p>LTS 内部还分阶段：前 12 个月是“活跃维护”，修 bug 也修安全问题；之后 18 个月只修安全问题。</p><p>本课程统一用 <strong>Node 24 LTS（代号 Krypton），最低 20.19</strong>。为什么是 20.19 这个具体数字？ 因为 Vite 8 用到了 Node 20.19 才稳定的一个模块加载特性，低于它启动就会直接报错。</p><div class="warning custom-block"><p class="custom-block-title">不要追 Current</p><p>Current 版本每半年换一次，新语法可能刚合进去就改。<strong>你追不动，也没有必要追。</strong></p><p>判断标准很简单：一个项目写清楚了自己要哪个版本，你就装哪个版本，不要去改它的要求。</p></div><h2 id="用-fnm-或-nvm-管版本" tabindex="-1">用 fnm 或 nvm 管版本 <a class="header-anchor" href="#用-fnm-或-nvm-管版本" aria-label="Permalink to &quot;用 fnm 或 nvm 管版本&quot;">​</a></h2><p>版本管理工具解决的就是“多个项目要不同 Node”的问题。主流有两个：</p><table tabindex="0"><thead><tr><th>工具</th><th>全称</th><th>平台</th><th>特点</th></tr></thead><tbody><tr><td>fnm</td><td>Fast Node Manager</td><td>Windows / macOS / Linux</td><td>用 Rust 写的，启动快；支持自动切换</td></tr><tr><td>nvm</td><td>Node Version Manager</td><td>macOS / Linux（Windows 用 nvm-windows）</td><td>出现早、资料多，但启动慢一些</td></tr></tbody></table><p>第 1 周你已经装过其中一个。这里用 fnm 演示，nvm 的命令几乎一一对应。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装 Node 24 的最新版</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看本机装了哪些版本（* 号表示当前正在用的）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 切换到 24</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设为默认版本（新开终端就用它）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看当前版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>nvm 的对应写法是 <code>nvm install 24</code>、<code>nvm use 24</code>、<code>nvm alias default 24</code>。</p><h3 id="让项目自己声明要哪个版本" tabindex="-1">让项目自己声明要哪个版本 <a class="header-anchor" href="#让项目自己声明要哪个版本" aria-label="Permalink to &quot;让项目自己声明要哪个版本&quot;">​</a></h3><p>光在自己机器上切来切去还不够，<strong>版本要求应该写在项目里，跟着 Git 一起提交</strong>。 两个常见的声明文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>24.9.0</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>24</span></span></code></pre></div><p>两个文件的作用一样，只是工具不同：fnm 读 <code>.node-version</code>，nvm 读 <code>.nvmrc</code>。 两个都写、内容一致，是最省事的做法。</p><p>再加上 fnm 的自动切换，进目录就自动切版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eval</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--use-on-cd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zsh)&quot;</span></span></code></pre></div><p><code>--use-on-cd</code> 的意思是：<strong>当你 <code>cd</code> 进一个带有 <code>.node-version</code> 的目录时， 自动切换到文件里写的版本。</strong> 这样你就不用记“这个项目要哪个版本”。</p><p>Windows PowerShell 里对应的写法是：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fnm env </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">use-on</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Out-String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Invoke-Expression</span></span></code></pre></div><h2 id="engines-字段-项目对-node-的硬性要求" tabindex="-1"><code>engines</code> 字段：项目对 Node 的硬性要求 <a class="header-anchor" href="#engines-字段-项目对-node-的硬性要求" aria-label="Permalink to &quot;\`engines\` 字段：项目对 Node 的硬性要求&quot;">​</a></h2><p><code>.node-version</code> 是给版本管理工具看的，<code>engines</code> 是给包管理器看的。它写在 <code>package.json</code> 里：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;campus-activity-admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;engines&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;=20.19.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pnpm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;=12.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;packageManager&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm@12.4.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>三个字段的分工：</p><table tabindex="0"><thead><tr><th>字段</th><th>谁读它</th><th>作用</th></tr></thead><tbody><tr><td><code>engines.node</code></td><td>pnpm / npm</td><td>Node 版本不满足时<strong>警告</strong>（默认不阻止安装）</td></tr><tr><td><code>engines.pnpm</code></td><td>pnpm</td><td>同上，针对包管理器版本</td></tr><tr><td><code>packageManager</code></td><td>Corepack</td><td>指定这个项目该用哪个包管理器的哪个版本</td></tr></tbody></table><p>默认情况下，<code>engines</code> 不满足只给警告，安装照样继续。这往往不是好事 —— 装完了再报一堆莫名其妙的错，不如一开始就拦下来。pnpm 提供了严格模式：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">engine-strict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span></code></pre></div><p>加上这一行，版本不满足时 <code>pnpm install</code> 会直接失败，并且明确告诉你期望什么、实际是什么。 <strong>本课程的项目统一加上这一行。</strong></p><div class="tip custom-block"><p class="custom-block-title">为什么第 1 周的报错里能看到 Expected 和 Got</p><p>因为那个项目已经配了 <code>engine-strict=true</code>。报错里的两行信息刚好回答了排查最重要的两个问题：</p><ul><li><code>Expected version: &gt;=20.19.0</code> —— 要求是什么</li><li><code>Got: v18.20.4</code> —— 你现在是什么</li></ul><p>看到这种报错，处理方式就一条：<strong>按它要求的版本装，而不是去改它的要求。</strong></p></div><h2 id="常见的-版本不对-报错长什么样" tabindex="-1">常见的“版本不对”报错长什么样 <a class="header-anchor" href="#常见的-版本不对-报错长什么样" aria-label="Permalink to &quot;常见的“版本不对”报错长什么样&quot;">​</a></h2><p>这一类报错的文案五花八门，但都有共同特征：<strong>报错里会同时出现一个版本号和一句语法或模块相关的抱怨。</strong> 认出来之后，处理方式都一样。</p><table tabindex="0"><thead><tr><th>报错片段</th><th>出现场景</th><th>真实原因</th></tr></thead><tbody><tr><td><code>ERR_PNPM_UNSUPPORTED_ENGINE</code></td><td>安装依赖时</td><td><code>engines</code> 不满足，且开了严格模式</td></tr><tr><td><code>You are using Node.js 18.x. Vite requires Node.js version 20.19+</code></td><td>启动 <code>vite</code></td><td>Vite 自己做了一次版本检查</td></tr><tr><td><code>SyntaxError: Unexpected token &#39;?&#39;</code></td><td>运行工具时</td><td>老 Node 不认识 <code>??</code> 这类新语法</td></tr><tr><td><code>Cannot find module &#39;node:path&#39;</code></td><td>运行脚本时</td><td><code>node:</code> 前缀在老版本里不完整</td></tr><tr><td><code>ReferenceError: fetch is not defined</code></td><td>代码里用了 <code>fetch</code></td><td>全局 <code>fetch</code> 是 Node 18 才稳定的</td></tr><tr><td><code>The engine &quot;node&quot; is incompatible with this module</code></td><td>安装某个依赖</td><td><strong>某个依赖自己的 <code>engines</code> 要求更高</strong></td></tr></tbody></table><p>最后一行值得单独说。有一种报错不是你的项目要求高，而是某个依赖要求高：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error some-package@3.0.0: The engine &quot;node&quot; is incompatible with this module.</span></span>
<span class="line"><span>Expected version &quot;&gt;=22&quot;. Got &quot;20.19.0&quot;</span></span></code></pre></div><p>这种时候你有两个选择：<strong>升级 Node</strong>，或者<strong>把那个依赖降到支持当前 Node 的版本</strong>。 选哪个取决于团队能不能一起升级 —— 不要自己一个人升完就提交，别人会跑不起来。</p><h2 id="版本切换后必须做的一件事" tabindex="-1">版本切换后必须做的一件事 <a class="header-anchor" href="#版本切换后必须做的一件事" aria-label="Permalink to &quot;版本切换后必须做的一件事&quot;">​</a></h2><p>切换 Node 版本之后，<strong>旧的 <code>node_modules</code> 可能不再适用</strong>。</p><p>原因是有些依赖在安装时会根据当前 Node 版本下载对应的二进制文件（比如构建工具的原生模块）。 你用 Node 18 装了一遍，切到 Node 24 之后那些二进制还是老的，运行时报出各种奇怪的错。</p><p>处理方式很简单，切完版本重新装一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">不要在不同 Node 版本之间来回切换同一个项目的 node_modules</p><p>这不是“重装一下就好了”的麻烦，而是排查成本极高的一类问题 —— 报错位置和真实原因 隔得很远，比如报错在“找不到某个 DLL 或 <code>.node</code> 文件”，而原因是三天前切过 Node 版本。</p><p><strong>规则：切了 Node 版本，就重装依赖，并且在排查单里记一笔。</strong></p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Node 是工具链的运行环境，本课程不用它写后端服务；<code>pnpm</code>、<code>vite</code> 都是跑在 Node 上的程序。</li><li>统一用 <strong>LTS</strong>，不要追 Current。本课程基线是 Node 24 LTS，最低 20.19。</li><li>用 fnm / nvm 管多版本，配合 <code>.node-version</code> 与 <code>--use-on-cd</code> 自动切换。</li><li><code>engines</code> 是项目对 Node 的要求，<code>.npmrc</code> 里的 <code>engine-strict=true</code> 让它从警告变成拦截。</li><li>看到“Expected / Got”这种报错，按要求的版本装，不要去改项目的要求。</li><li>切换 Node 版本后要重装 <code>node_modules</code>。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><details class="details custom-block"><summary>坑 1：装完新版本，<code>node -v</code> 还是老的</summary><p><strong>现象</strong>：<code>fnm install 24</code> 成功，<code>fnm use 24</code> 也成功，但新开一个终端 <code>node -v</code> 又变回旧版本。</p><p><strong>原因</strong>：<code>fnm use</code> 只对当前这个终端会话生效。新开的终端走的是默认版本。</p><p><strong>处理</strong>：执行 <code>fnm default 24</code> 把默认版本改掉，然后检查 shell 配置里有没有 <code>eval &quot;$(fnm env ...)&quot;</code> 这一行。没有这一行的话，fnm 的版本设置根本不会注入到终端里。</p></details><details class="details custom-block"><summary>坑 2：Windows 上提示“禁止运行脚本”</summary><p><strong>现象</strong>：在 PowerShell 里执行 <code>fnm env | Out-String | Invoke-Expression</code> 报 <code>无法加载文件，因为在此系统上禁止运行脚本</code>。</p><p><strong>原因</strong>：PowerShell 默认的执行策略不允许运行脚本。</p><p><strong>处理</strong>：以管理员身份打开 PowerShell，执行 <code>Set-ExecutionPolicy -ExecutionPolicy RemoteSigned -Scope CurrentUser</code>，输入 <code>Y</code> 确认。 <code>-Scope CurrentUser</code> 表示只影响你自己，不改全局策略。</p></details><details class="details custom-block"><summary>坑 3：团队里有人 Node 版本高，有人低</summary><p><strong>现象</strong>：A 同学在 Node 24 上开发一切正常，B 同学 Node 20 报语法错误，两人代码完全一样。</p><p><strong>原因</strong>：项目没有把版本要求写进仓库，全靠各人自己记得。</p><p><strong>处理</strong>：按顺序做三件事 —— 提交 <code>.node-version</code>、在 <code>package.json</code> 里写 <code>engines</code>、 在 <code>.npmrc</code> 里加 <code>engine-strict=true</code>。</p><p><strong>判断标准：新同学克隆下来之后，不做任何额外确认就能跑起来。</strong> 做不到就是配置没写全。</p></details><details class="details custom-block"><summary>坑 4：升级 Node 之后 ESLint 报一堆 <code>Parsing error</code></summary><p><strong>现象</strong>：切到 Node 24 后，<code>pnpm lint</code> 报大量语法解析错误，代码却没改过。</p><p><strong>原因</strong>：<code>node_modules</code> 是旧版本时代装的，里面的解析器二进制和当前 Node 不匹配。</p><p><strong>处理</strong>：删掉 <code>node_modules</code> 重装。如果还不行，再清一次 pnpm 缓存 （<code>pnpm store prune</code>），然后再装。</p><p><strong>记住顺序：先重装，再清缓存。</strong> 反过来做会多花十几分钟下载。</p></details><details class="details custom-block"><summary>坑 5：<code>packageManager</code> 字段和实际用的包管理器不一致</summary><p><strong>现象</strong>：<code>package.json</code> 里写的是 <code>&quot;packageManager&quot;: &quot;pnpm@12.4.1&quot;</code>，但你在用 npm 安装， 结果报 <code>This project is configured to use pnpm</code>。</p><p><strong>原因</strong>：Corepack 读到了 <code>packageManager</code> 字段，发现你用的不是它指定的工具。</p><p><strong>处理</strong>：两条路 —— 要么按它的要求用 pnpm；要么在执行时关掉 Corepack 检查。 <strong>推荐第一条</strong> —— 字段是团队统一约定的，不要为了图方便绕过去。</p></details><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><details class="details custom-block"><summary>练习 1：给你的机器装两个 Node 版本</summary><p>要求：装上 Node 24 和 Node 20.19，能在同一个终端里来回切换，并把切换结果记录下来。</p><p>命令思路：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20.19.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20.19.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 应该是 v20.19.x</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 应该是 v24.x</span></span></code></pre></div><p><strong>验收点</strong>：<code>fnm list</code> 里有两个版本，且 <code>*</code> 号会跟着 <code>fnm use</code> 移动。 如果在某个版本下 <code>node -v</code> 输出的还是另一个版本，说明 shell 配置有问题，回去查坑 1。</p></details><details class="details custom-block"><summary>练习 2：造一个“版本不对”的报错</summary><p>在练习目录里建一个最小项目，故意把 <code>engines</code> 写成超出你当前版本的范围， 加上 <code>engine-strict=true</code>，然后执行 <code>pnpm install</code>，观察报错。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;engine-test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;private&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;engines&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;=99.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">engine-strict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span></code></pre></div><p><strong>为什么值得做</strong>：你把报错“制造”出来过一次，以后在真实项目里遇到就不会慌。 注意观察报错里的 <code>Expected</code> 与 <code>Got</code> 两行 —— 这两行就是排查的全部线索。</p><p><strong>接着做一步</strong>：把 <code>engine-strict=true</code> 去掉再装一次，看看是不是只给警告不报错。 对比之后你就明白这个配置的作用了。</p></details><details class="details custom-block"><summary>练习 3：写一份 .node-version 并验证自动切换</summary><p>在项目里创建 <code>.node-version</code>，内容写 <code>20.19.0</code>。然后：</p><ol><li>确保 shell 配置里有 <code>--use-on-cd</code>。</li><li>退出当前目录，再重新进入。</li><li>执行 <code>node -v</code>，看是否自动切成了 <code>20.19.0</code>。</li></ol><p><strong>没生效怎么办</strong>：先确认 <code>fnm env --use-on-cd</code> 这一行在配置文件里（不是 <code>.zshrc</code> 写成了 <code>.bashrc</code>），然后 <code>source ~/.zshrc</code> 让配置生效，再试一次。</p><p><strong>进阶</strong>：把 <code>.node-version</code> 改成 <code>24</code>，再进一次目录，看是否切换。 体会一下“写大版本号”和“写精确版本号”的区别 —— 前者会自动用最新的 24.x。</p></details><details class="details custom-block"><summary>练习 4：认出五条报错分别是什么原因</summary><p>下面五条报错，分别是什么问题、第一步该查什么？不查资料，凭这一节学到的内容回答。</p><ol><li><code>ERR_PNPM_UNSUPPORTED_ENGINE ... Expected version: &gt;=20.19.0, Got: v18.20.4</code></li><li><code>SyntaxError: Unexpected token &#39;??&#39;</code></li><li><code>error vite@8.3.0: The engine &quot;node&quot; is incompatible with this module. Expected &quot;&gt;=20.19&quot;</code></li><li><code>pnpm: command not found</code></li><li><code>fnm: command not found</code></li></ol><p><strong>参考思路</strong>：区分三件事 —— <strong>Node 版本不对</strong>（1、3）、<strong>语法特性不支持</strong>（2）、 <strong>工具本身没装或没进 PATH</strong>（4、5）。第 4 题如果 Node 是好的，说明 pnpm 没装； 第 5 题说明 fnm 装了但 shell 没加载，回去查 shell 配置。</p><p><strong>关键判断</strong>：报错里出现 <code>Expected</code> / <code>Got</code> 就是版本问题；出现 <code>command not found</code> 就是安装或 PATH 问题。这两类占日常报错的一大半。</p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit02/">单元 2 导学</a> · 下一节：<a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2 包管理器与依赖安装</a></p>`,75)])])}const g=e(n,[["render",d]]);export{k as __pageData,g as default};
